"use client";

import React from "react";
import { ExamCurriculum } from "./mockExamTypes";
import { CustomImage } from "@/components/ui";

interface CurriculumCardProps {
    curriculum: ExamCurriculum;
    onStartExam: (curriculum: ExamCurriculum) => void;
}

export default function CurriculumCard({
    curriculum,
    onStartExam,
}: CurriculumCardProps) {
    const {
        code,
        title,
        description,
        metricLabel,
        metricValue,
        metricTotal,
        availableMocks,
        lastAttempt,
        iconType,
    } = curriculum;

    // Render crest/logo
    const renderIcon = () => {
        if (iconType === "waec") {
            return (
                <div className="w-8 h-8 rounded-full flex items-center justify-center text-amber-400 font-bold text-xs shadow-xs ">
                    <svg width="32" height="31" viewBox="0 0 32 31" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
                        <rect width="32" height="31" fill="url(#pattern0_420_4572)" />
                        <defs>
                            <pattern id="pattern0_420_4572" patternContentUnits="objectBoundingBox" width="1" height="1">
                                <use xlinkHref="#image0_420_4572" transform="matrix(0.00129175 0 0 0.00132824 -0.0452842 -0.112994)" />
                            </pattern>
                            <image id="image0_420_4572" width="840" height="906" preserveAspectRatio="none" xlinkHref="data:image/png;base64," />
                        </defs>
                    </svg>

                </div>
            );
        }
        if (iconType === "neco") {
            return (
                <div className="w-8 h-8 rounded-full flex items-center justify-center text-white font-bold text-[10px] shadow-xs ">
                    <svg width="32" height="29" viewBox="0 0 32 29" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
                        <rect width="32" height="29" fill="url(#pattern0_420_4607)" />
                        <defs>
                            <pattern id="pattern0_420_4607" patternContentUnits="objectBoundingBox" width="1" height="1">
                                <use xlinkHref="#image0_420_4607" transform="matrix(0.00325733 0 0 0.0035461 -0.325733 -0.152482)" />
                            </pattern>
                            <image id="image0_420_4607" width="528" height="378" preserveAspectRatio="none" xlinkHref="data:image/png;base64," />
                        </defs>
                    </svg>

                </div>
            );
        }
        // JAMB or POST-UTME green seal
        return (
            <div className="w-8 h-8 rounded-full flex items-center justify-center text-white shadow-xs ">
                <svg width="32" height="31" viewBox="0 0 32 31" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
                    <rect width="32" height="31" fill="url(#pattern0_420_4555)" />
                    <defs>
                        <pattern id="pattern0_420_4555" patternContentUnits="objectBoundingBox" width="1" height="1">
                            <use xlinkHref="#image0_420_4555" transform="matrix(0.00183824 0 0 0.00187617 -0.527574 -0.212007)" />
                        </pattern>
                        <image id="image0_420_4555" width="1120" height="750" preserveAspectRatio="none" xlinkHref="data:image/png;base64," />
                    </defs>
                </svg>

            </div>
        );
    };

    return (
        <div className="bg-white border border-[#E2EAF4] rounded-2xl p-6 flex flex-col justify-between shadow-xs hover:shadow-md transition-shadow">
            <div>
                {/* Top Row: Crest + Performance Metric */}
                <div className="flex items-center justify-between mb-4">
                    {renderIcon()}
                    {/* <div className=" w-8 h-8  bg-accent-350" >
                        <CustomImage src={"/images/landing/jamb.png"} alt="jamb" fill />
                    </div> */}

                    <div className="flex items-baseline gap-1 text-xs text-neutral-500 font-medium">
                        <span>{metricLabel}:</span>
                        <span className="font-bold text-neutral-900 text-sm">
                            {metricValue}
                        </span>
                        {metricTotal && (
                            <span className="text-[11px] text-neutral-400 font-normal">
                                {metricTotal}
                            </span>
                        )}
                    </div>
                </div>

                {/* Title & Description */}
                <h3 className="text-xl font-bold text-neutral-900 mb-1.5">
                    {title}
                </h3>
                <p className="text-xs text-neutral-500 leading-relaxed mb-6">
                    {description}
                </p>

                {/* Info Row: Available Mocks & Last Attempt */}
                <div className="flex items-center justify-between pt-2 border-t border-neutral-100">
                    <div className="flex flex-col">
                        <span className="text-[11px] text-neutral-400 font-medium">
                            Available mocks
                        </span>
                        <span className="text-xs font-bold text-neutral-800 mt-0.5">
                            {availableMocks}
                        </span>
                    </div>

                    <div className="flex flex-col text-right">
                        <span className="text-[11px] text-neutral-400 font-medium">
                            Last Attempt
                        </span>
                        <span className="text-xs font-bold text-neutral-800 mt-0.5">
                            {lastAttempt}
                        </span>
                    </div>
                </div>
            </div>

            {/* Start Exam Button */}
            <button
                type="button"
                onClick={() => onStartExam(curriculum)}
                className="w-full mt-6 py-2.5 px-4 rounded-xl border border-primary-300 text-primary-300 font-semibold text-xs sm:text-sm hover:bg-primary-50 active:scale-[0.98] transition-all flex items-center justify-center cursor-pointer"
            >
                Start Exam
            </button>
        </div>
    );
}
